  q018: { prompt: '10, 50, మరియు 100 రూపాయల నోట్లను ఉపయోగించి, ఏ కలయిక సరిగ్గా 160 రూపాయలు అవుతుంది?', choices: ['ఒక 100 + ఒక 50 + ఒక 10', 'ఒక 100 + ఒక 50', 'మూడు 50 నోట్లు', 'ఒక 100 + ఒక 10'] },
  q019: { prompt: 'డిసెంబర్ నుండి నెలలను వెనక్కి చెప్తే, డిసెంబర్ తర్వాత వెంటనే వచ్చేది ఏ నెల?', choices: ['జనవరి', 'నవంబర్', 'అక్టోబర్', 'ఫిబ్రవరి'] },
  q020: { prompt: '1 నుండి 10 వరకు లెక్కపెడుతూ, ప్రతి సరి సంఖ్యకు బదులు "వదిలేయి" అని చెప్తే, 4కి బదులు మీరు ఏమి చెప్తారు?', choices: ['4', 'వదిలేయి', 'నాలుగు', 'ఏమీ లేదు'] },
  q021: { prompt: 'మీ దగ్గర 80 రూపాయలు ఉన్నాయి. మీరు 25 రూపాయలకు కిరాణా సామాను, 12 రూపాయలకు పుస్తకం కొన్నారు. మీ దగ్గర ఎంత మిగిలింది?', choices: ['41', '43', '45', '47'] },
