// Looks up the translated { prompt, choices } for one Question Bank item.
// Falls back to English if the requested language is somehow missing (it
// never should be -- see check-question-bank.mjs) or if `id` isn't found
// at all (defensive only; every id in QUESTION_BANK has an entry here).
export function questionText(id, language = DEFAULT_LANGUAGE) {
  const en = QUESTION_BANK_TEXT.en[id];
  const table = QUESTION_BANK_TEXT[language] || QUESTION_BANK_TEXT[DEFAULT_LANGUAGE];
  return (table && table[id]) || en || null;
}
